const payload = $input.first().json || {};
const stdout = String(payload.stdout || '').trim();
const stderr = String(payload.stderr || '').trim();
const error = String(payload.error || '').trim();

const fallback = {
  timestamp: new Date().toISOString(),
  searched: 0,
  unique: 0,
  scored: 0,
  relevant: 0,
  applied: 0,
  skipped: 0,
  failed: 1,
  topJobs: [],
  appliedJobs: [],
  skippedJobs: [],
  failedJobs: [{ id: null, title: 'pipeline', company: 'pipeline', source: 'pipeline', error: error || stderr || 'No JSON output from pipeline' }],
};

let result = fallback;
if (stdout) {
  try {
    const jsonStart = stdout.indexOf('{\n'); const jsonStr = jsonStart >= 0 ? stdout.slice(jsonStart) : stdout; // Robust JSON extraction: find {"timestamp" pattern in potentially contaminated stdout
    const tsIdx = stdout.indexOf('"timestamp"');
    if (tsIdx > 0) {
      const braceIdx = stdout.lastIndexOf('{', tsIdx);
      if (braceIdx >= 0) {
        result = JSON.parse(stdout.slice(braceIdx));
      } else {
        result = JSON.parse(stdout);
      }
    } else {
      result = JSON.parse(stdout);
    }
  } catch (parseError) {
    result = {
      ...fallback,
      failedJobs: [{
        id: null,
        title: 'pipeline',
        company: 'pipeline',
        source: 'pipeline',
        error: `Failed to parse stdout JSON: ${parseError.message}`
      }]
    };
  }
}

const esc = (value) => String(value || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const sourceLabel = (source) => source === 'jobkorea' ? 'JK' : source === 'wanted' ? 'W' : '??';

const appliedLines = (Array.isArray(result.appliedJobs) && result.appliedJobs.length > 0)
  ? result.appliedJobs.map((job) => `[${sourceLabel(job.source)}] ${esc(job.company)} - ${esc(job.title)} - ${esc(job.url)}`).join('\n')
  : '없음';

const warnings = Array.isArray(result.sessionWarnings) && result.sessionWarnings.length > 0;
const warningBlock = warnings ? '⚠️ <b>세션 경고:</b>\n' + result.sessionWarnings.map(w => esc(w)).join('\n') + '\n\n' : '';

const topLines = (Array.isArray(result.topJobs) && result.topJobs.length > 0)
  ? result.topJobs.slice(0, 5).map((job) => `[${sourceLabel(job.source)}][${esc(job.score)}] ${esc(job.company)} - ${esc(job.title)} - ${esc(job.url)}`).join('\n')
  : '없음';

const text = `🔍 <b>공고 검색 + 자동지원 결과</b>\n\n📊 검색 ${result.searched || 0}건 → 매칭 ${result.scored || 0}건 → 관련 ${result.relevant || 0}건\n✅ 지원: ${result.applied || 0}건 | ⏭️ 이미지원: ${result.skipped || 0}건 | ❌ 실패: ${result.failed || 0}건\n\n🏆 <b>지원 완료:</b>\n${appliedLines}\n\n🎯 <b>추천 공고 TOP 5:</b>\n${topLines}\n\n⏰ ${esc(result.timestamp || new Date().toISOString())}`;

return [{ json: { ...result, stderr, error, text } }];
